<script>
window.previewSettingsImage=function(event){const file=event.target.files&&event.target.files[0];if(!file)return;const valid=['image/jpeg','image/png','image/webp','image/jpg'];if(!valid.includes(file.type)){event.target.value='';window.alert('Please upload a valid image (JPEG, PNG, or WebP).');return}if(file.size>2*1024*1024){event.target.value='';window.alert('Image size must be less than 2MB.');return}const reader=new FileReader();reader.onload=function(e){const display=document.getElementById('settingsAvatarDisplay');if(display)display.innerHTML='<img src="'+e.target.result+'" alt="Profile photo preview">'};reader.readAsDataURL(file)};
(function(){const bio=document.getElementById('settings_bio'),count=document.getElementById('settingsBioCharCount');if(bio&&count){const update=function(){count.textContent=bio.value.length};bio.addEventListener('input',update);update()}})();
</script>
